  "claims": [
    {
      "claim": "Esaxerenone, a pyrrole-based drug with a sulfonyl-containing substituent and fluorinated aryl group, has absolute oral bioavailability 90.8% postprandially in healthy Japanese subjects, supporting high F for the similarly substituted pyrrole query.",
      "card_ids": ["C01"]
    },
    {
      "claim": "Dabrafenib, a heteroaromatic sulfonamide with a difluorophenyl group, has absolute oral bioavailability 95% in humans, showing that sulfonamide/difluorophenyl-containing molecules can be very well absorbed orally.",
      "card_ids": ["C06", "C28"]
    },
    {
      "claim": "Voriconazole, a fluorinated heteroaryl with a difluorophenyl group, has oral bioavailability of approximately 96% in the fasted state, supporting high oral bioavailability for fluorinated heteroaromatic compounds.",
      "card_ids": ["C07", "C29"]
    },
    {
      "claim": "Safinamide, a small-molecule fluorophenyl drug, has absolute oral bioavailability of 95.3% in fed subjects, further supporting high oral bioavailability for low-molecular-weight fluorinated compounds.",
      "card_ids": ["C05"]
    },
    {
      "claim": "Additional L1 records for cerivastatin, trovafloxacin, lumiracoxib, rufinamide, and glibenclamide report oral bioavailability values of 60-91%, all well above the 20% threshold.",
      "card_ids": ["C09", "C10", "C12", "C08", "C31"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C01", "C05", "C06", "C07", "C08", "C09", "C10", "C12", "C28", "C29", "C31"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "No matched oral versus IV exposure data are available for the query.",
    "No human pharmacokinetic data are available for the query; transfer relies on structural analogy to related contexts.",
    "No query-specific solubility/dissolution or first-pass/efflux data are available."
  ],
  "decision_summary": "All visible L1 records from structurally related pyrrole/sulfonamide/fluorinated-aryl contexts report absolute oral bioavailability values of 60-96%, all well above the 20% threshold, and the physicochemical prior is favorable (logD 2.53, TPSA 60.3, MW 410). No affirmative evidence supports F < 20%. Therefore, predict high with moderate confidence."
}

